from mathlib import *
QB = []
def Q(l, q, o, e, chk=None):
    """o[0] is the right answer; '@' = fill it from chk. chk (if given) must equal o[0]."""
    o = list(o)
    if o[0] == '@': o[0] = str(chk)
    elif chk is not None: assert str(chk) == o[0], (q, chk, o[0])
    assert len(o) == 4 and len(set(o)) == 4, (q, o)
    QB.append([l, sp(q), [sp(x) for x in o], sp(e)])
def Fr(a, b): f = Fraction(a, b); return f"{f.numerator}/{f.denominator}"

# ---------- L1 classification & primes ----------
Q("L1","How many prime numbers are there from 1 to 100?",["@","24","26","21"],"2, 3, 5 … 97: 15 up to 50 and 10 from 51 to 100 → 25.",len(primes(1,100)))
Q("L1","How many prime numbers are there from 1 to 200?",["@","45","48","50"],"25 up to 100 and 21 from 101 to 200 → 46.",len(primes(1,200)))
Q("L1","How many prime numbers are there between 1 and 1000?",["@","158","178","148"],"A fixed fact: 168 primes below 1000.",len(primes(1,1000)))
Q("L1","Which is the smallest 3-digit prime number?",["101","103","107","111"],"101 is not divisible by 2, 3, 5 or 7. 111 = 3 × 37.",min(primes(100,999)))
Q("L1","Which is the largest 3-digit prime number?",["997","999","991","993"],"999 = 27 × 37 and 993 = 3 × 331; 991 is prime but smaller than 997.",max(primes(100,999)))
Q("L1","Which of the following is a prime number?",["137","133","143","161"],"133 = 7 × 19, 143 = 11 × 13, 161 = 7 × 23; 137 has no prime factor up to 11.")
assert isprime(137) and not any(isprime(x) for x in (133,143,161))
Q("L1","Which of the following is NOT a prime number?",["91","89","97","83"],"91 = 7 × 13.")
assert not isprime(91) and all(isprime(x) for x in (89,97,83))
Q("L1","What is the average of all prime numbers between 80 and 100?",["@","88.33","90.5","87.67"],"83, 89, 97 → 269/3 = 89.67.",f"{sum(primes(80,100))/len(primes(80,100)):.2f}")
Q("L1","x, y, z are distinct primes with x < y < z and x + y + z = 70. Which of the following can be z?",["37","29","43","31"],"x = 2, y + z = 68. z = 37 → y = 31 ✓; 29 → 39, 43 → 25 are not prime; 31 → y = 37 > z.")
assert isprime(31) and not isprime(39) and not isprime(25)
Q("L1","x, y and z are primes with x + y + z = 38. What is the largest possible value of x?",["@","29","37","23"],"38 is even → one prime is 2; x + y = 36 with y = 5 gives x = 31.",max(x for x in primes(2,38) for y in primes(2,38) for z in primes(2,38) if x+y+z==38))
Q("L1","What is the sum of all prime numbers from 1 to 20?",["@","75","58","79"],"2 + 3 + 5 + 7 + 11 + 13 + 17 + 19 = 77.",sum(primes(1,20)))
Q("L1","0.363636… expressed as a fraction is:",["@","9/25","3/11","36/90"],"36/99 = 4/11.",Fr(36,99))
Q("L1","0.2333… expressed as a fraction is:",["@","23/90","23/99","2/9"],"(23 − 2)/90 = 21/90 = 7/30.",Fr(21,90))
Q("L1","0.1454545… expressed as a fraction is:",["@","16/99","145/999","4/25"],"(145 − 1)/990 = 144/990 = 8/55.",Fr(144,990))
Q("L1","Which of the following fractions gives a terminating decimal?",["7/80","5/12","3/14","11/30"],"80 = 2⁴ × 5 has only 2s and 5s; 12, 14 and 30 contain 3 or 7.")
Q("L1","Which of the following is an irrational number?",["√12","√49","0.333…","22/7"],"√12 = 2√3 never ends or repeats; √49 = 7, 0.333… = 1/3 and 22/7 are rational.")
Q("L1","Which of these is the smallest perfect number?",["6","28","1","12"],"1 + 2 + 3 = 6. 28 is the next one.")
Q("L1","Which pair is a pair of twin primes?",["41, 43","47, 49","51, 53","37, 39"],"Twin primes differ by 2 and both are prime; 49, 51 and 39 are composite.")
Q("L1","Which pair of numbers is co-prime?",["16, 9","12, 18","15, 25","14, 21"],"HCF(16, 9) = 1. The others share 6, 5 and 7.")
Q("L1","The product of two co-prime numbers is 117. Their LCM is:",["117","1","39","13"],"For co-prime numbers HCF = 1, so LCM = product = 117.")
Q("L1","Which of the following is the smallest odd composite number?",["9","15","1","3"],"1 is neither, 3 is prime, 9 = 3 × 3.")

# ---------- L2 unit digit ----------
def ud(*terms): return terms
Q("L2","Find the unit digit of 232 × 235.",["0","5","6","2"],"2 × 5 = 10 → 0.",(232*235)%10)
Q("L2","Find the unit digit of 628 + 493 + 589.",["@","8","1","4"],"8 + 3 + 9 = 20 → 0.",(628+493+589)%10)
Q("L2","Find the unit digit of 2383 − 1689.",["@","6","2","3"],"13 − 9 = 4.",(2383-1689)%10)
Q("L2","Find the unit digit of (382)^575.",["@","2","4","6"],"75 ÷ 4 leaves 3 → 2³ = 8.",pow(382,575,10))
Q("L2","Find the unit digit of (187)^282 × (529)^321 × (343)^236.",["@","9","7","3"],"7² → 9, 9 (odd) → 9, 3⁴ → 1: 9 × 9 × 1 = 81 → 1.",(pow(187,282,10)*pow(529,321,10)*pow(343,236,10))%10)
Q("L2","Find the unit digit of (789)^315 + (232)^644 + (528)^253.",["@","1","7","9"],"9 + 6 + 8 = 23 → 3.",(pow(789,315,10)+pow(232,644,10)+pow(528,253,10))%10)
Q("L2","Find the unit digit of (982)^481 − (219)^241.",["@","7","1","9"],"2 − 9 → 12 − 9 = 3.",(pow(982,481)-pow(219,241))%10)
Q("L2","Find the unit digit of 1! + 2! + 3! + … + 100!.",["@","0","9","1"],"From 5! every term ends in 0; 1 + 2 + 6 + 24 = 33 → 3.",sum(math.factorial(k) for k in range(1,101))%10)
Q("L2","Find the unit digit of 7^95.",["@","7","9","1"],"95 ÷ 4 leaves 3 → 7³ = 343 → 3.",pow(7,95,10))
Q("L2","Find the unit digit of 3^65 × 6^59 × 7^71.",["@","2","6","8"],"3¹ → 3, 6 → 6, 7³ → 3: 3 × 6 × 3 = 54 → 4.",(pow(3,65,10)*pow(6,59,10)*pow(7,71,10))%10)
Q("L2","Find the unit digit of 4^1997.",["@","6","2","8"],"Odd power of 4 → 4.",pow(4,1997,10))
Q("L2","Find the unit digit of 9^1000.",["@","9","3","7"],"Even power of 9 → 1.",pow(9,1000,10))
Q("L2","Find the unit digit of (1739)^243 × (1265)^347 × (3418)^2.",["@","5","4","8"],"9 × 5 × 4 = 180 → 0 (an even digit times 5).",(pow(1739,243,10)*pow(1265,347,10)*pow(3418,2,10))%10)
Q("L2","Find the unit digit of 2^100 − 1.",["@","6","1","4"],"2¹⁰⁰: 00 ÷ 4 leaves 0 → 2⁴ → 6; 6 − 1 = 5.",(pow(2,100)-1)%10)
Q("L2","Find the unit digit of 13^2003.",["@","3","9","1"],"03 ÷ 4 leaves 3 → 3³ = 27 → 7.",pow(13,2003,10))
Q("L2","Find the unit digit of 8^43 + 2^43.",["@","4","2","6"],"8³ → 2 and 2³ → 8: 2 + 8 = 10 → 0.",(pow(8,43,10)+pow(2,43,10))%10)
Q("L2","Find the last two digits of 31^786.",["@","61","91","11"],"Tens digit = unit digit of 3 × 786 = 2358 → 8; answer 81.",f"{pow(31,786,100):02d}")
Q("L2","Find the unit digit of 1 × 3 × 5 × 7 × … × 99 (product of odd numbers).",["@","0","1","3"],"An odd product containing 5 always ends in 5.",math.prod(range(1,100,2))%10)

# ---------- L3 number of factors ----------
def tot(n): return ndiv(n)
def odd(n): return len([d for d in divisors(n) if d%2])
def even(n): return len([d for d in divisors(n) if d%2==0])
def sq(n): return len([d for d in divisors(n) if int(d**.5)**2==d])
def cube(n): return len([d for d in divisors(n) if round(d**(1/3))**3==d])
def coprime_pairs(n):
    D = divisors(n); return sum(1 for i,a in enumerate(D) for b in D[i:] if math.gcd(a,b)==1)
Q("L3","Find the total number of factors of 360.",["@","20","18","36"],"360 = 2³ × 3² × 5 → 4 × 3 × 2 = 24.",tot(360))
Q("L3","Find the total number of factors of 480.",["@","20","30","16"],"480 = 2⁵ × 3 × 5 → 6 × 2 × 2 = 24.",tot(480))
Q("L3","Find the number of even factors of 360.",["@","16","20","12"],"3 × (2 + 1)(1 + 1) = 18.",even(360))
Q("L3","Find the number of odd factors of 360.",["@","8","4","12"],"(2 + 1)(1 + 1) = 6.",odd(360))
Q("L3","N = 56 = 2³ × 7. Find the number of composite factors of N.",["@","6","4","3"],"Total 8 − 2 primes − 1 = 5.",tot(56)-len(factorize(56))-1)
Q("L3","Find the number of prime factors of 720 (distinct).",["@","2","4","5"],"720 = 2⁴ × 3² × 5 → primes 2, 3, 5.",len(factorize(720)))
Q("L3","Find the number of composite factors of 720.",["@","27","30","24"],"30 − 3 − 1 = 26.",tot(720)-3-1)
Q("L3","How many factors of 720 are perfect squares?",["@","4","8","3"],"2 from {0, 2, 4}, 3 from {0, 2}, 5 from {0} → 3 × 2 × 1 = 6.",sq(720))
Q("L3","How many factors of 720 are perfect cubes?",["@","1","3","4"],"1 and 8 → 2.",cube(720))
Q("L3","How many factors of 720 are divisible by 10?",["@","10","15","8"],"Factors of 72 = 2³ × 3² → 4 × 3 = 12.",len([d for d in divisors(720) if d%10==0]))
Q("L3","How many factors of 14400 are divisible by 18 but not by 36?",["@","15","18","6"],"Factors of 800 (18) − factors of 400 (15) = 3.",len([d for d in divisors(14400) if d%18==0 and d%36]))
Q("L3","When 732 is divided by a positive integer x, the remainder is 12. How many values of x are possible?",["@","30","19","10"],"x divides 720 and x > 12: 30 − 10 = 20.",len([x for x in range(1,733) if 732%x==12]))
Q("L3","In how many ways can a pair of co-prime factors of 56 be chosen?",["@","8","12","9"],"(3 + 1)(1 + 1) + 3 × 1 = 11.",coprime_pairs(56))
Q("L3","N = 720 = 2⁴ × 3² × 5. In how many ways can a pair of co-prime factors of N be chosen?",["@","30","38","60"],"30 + (8 + 2 + 4) + 3 × 8 = 68.",coprime_pairs(720))
Q("L3","Which of the following numbers has an odd number of factors?",["196","198","200","192"],"Only perfect squares have an odd number of factors: 196 = 14².")
assert tot(196)%2==1 and all(tot(x)%2==0 for x in (198,200,192))
Q("L3","How many numbers between 1 and 100 have exactly three factors?",["@","3","5","25"],"Exactly 3 factors = square of a prime: 4, 9, 25, 49 → 4.",len([n for n in range(1,101) if tot(n)==3]))
Q("L3","In how many ways can 360 be written as a product of two natural numbers?",["@","24","6","18"],"24 factors, 360 is not a perfect square → 24/2 = 12.",len([a for a in divisors(360) if a*a<=360]))
Q("L3","Find the number of factors of 2^4 × 3^5 × 5^2 that are perfect squares.",["@","27","12","15"],"(2 + 1)(2 + 1)(1 + 1) = 18.",sq(2**4*3**5*5**2))

# ---------- L4 sum, product ----------
def ssum(n, f=lambda d: True): return sum(d for d in divisors(n) if f(d))
Q("L4","Find the sum of all factors of 360.",["@","1092","1080","1260"],"15 × 13 × 6 = 1170.",ssum(360))
Q("L4","Find the sum of all even factors of 360.",["@","1170","1080","1012"],"14 × 13 × 6 = 1092.",ssum(360,lambda d:d%2==0))
Q("L4","Find the sum of all odd factors of 360.",["@","72","84","91"],"13 × 6 = 78.",ssum(360,lambda d:d%2==1))
Q("L4","Find the sum of all even factors of 720.",["@","2418","1092","2200"],"(2 + 4 + 8 + 16) × 13 × 6 = 2340.",ssum(720,lambda d:d%2==0))
Q("L4","Find the sum of all odd factors of 720.",["@","156","39","72"],"The power of 2 does not matter: 13 × 6 = 78.",ssum(720,lambda d:d%2==1))
Q("L4","Find the sum of all factors of 100.",["@","216","117","200"],"7 × 31 = 217.",ssum(100))
Q("L4","Find the sum of all factors of 1000.",["@","2430","1560","2000"],"1000 = 2³ × 5³ → (1 + 2 + 4 + 8)(1 + 5 + 25 + 125) = 15 × 156 = 2340.",ssum(1000))
Q("L4","Find the sum of the reciprocals of all factors of 16.",["@","15/16","2","1"],"Sum of factors 31 ÷ 16.",Fr(ssum(16),16))
Q("L4","The sum of the reciprocals of the factors of 28 is:",["@","56/27","1","3/2"],"σ(28) = 56 → 56/28 = 2 (28 is a perfect number).",Fr(ssum(28),28) if Fr(ssum(28),28)!="2/1" else "2")
Q("L4","What is the product of all factors of 360?",["360^12","360^24","360^6","24^360"],"24 factors → N^(24/2) = 360¹².")
assert tot(360)==24
Q("L4","What is the product of all factors of 36?",["6^9","36^9","6^18","36^4"],"9 factors → 36^(9/2) = 6⁹.")
assert math.prod(divisors(36))==6**9
Q("L4","Which of these is a perfect number?",["496","500","484","512"],"σ(496) = 992 = 2 × 496.")
assert ssum(496)==2*496 and all(ssum(x)!=2*x for x in (500,484,512))
Q("L4","Find the sum of all factors of 2^5 × 3^2.",["@","403","728","1001"],"63 × 13 = 819.",ssum(2**5*3**2))

# ---------- L5 divisibility ----------
def digs(fmt, cond):
    return [(x,y) for x in range(10) for y in range(10) if cond(int(fmt.format(x=x,y=y)))]
r = [(x,y,z) for x in range(10) for y in range(10) for z in range(10) if int(f"479{x}{y}{z}")%1001==0]
Q("L5","If the six-digit number 479xyz is exactly divisible by 7, 11 and 13, then (y + z) × x is:",["@","48","84","56"],"479479 → x = 4, y = 7, z = 9 → 16 × 4 = 64.",(r[0][1]+r[0][2])*r[0][0])
r = digs("35345{x}{y}", lambda n: n%40==0)
Q("L5","If the seven-digit number 35345xy is divisible by 40, the minimum value of 4x + 5y is:",["@","0","24","12"],"y = 0 and 5x0 divisible by 8 → x = 2 or 6 → least 8.",min(4*x+5*y for x,y in r))
r = digs("7{y}9745{x}2", lambda n: n%72==0)
Q("L5","If the 8-digit number 7y9745x2 is divisible by 72, find (2x − y) for the greatest value of x.",["@","14","18","12"],"x = 9 (592 ÷ 8 ✓), digit sum 52 + y → y = 2 → 18 − 2 = 16.",[2*x-y for x,y in r if x==max(a for a,b in r)][0])
r = digs("535{x}{y}", lambda n: n%231==0)
Q("L5","If the 5-digit number 535ab is divisible by 3, 7 and 11, the value of a² − b² + ab is:",["@","85","77","108"],"53592 = 231 × 232 → a = 9, b = 2: 81 − 4 + 18 = 95.",[x*x-y*y+x*y for x,y in r][0])
Q("L5","Which digit in place of * makes 5*2 divisible by 8?",["5","4","3","2"],"552 = 8 × 69.")
assert 552%8==0 and all(int(f"5{d}2")%8 for d in (4,3,2))
r = [d for d in range(10) if int(f"6{d}5341")%11==0]
Q("L5","What is the value of d if the number 6d5341 is divisible by 11?",["@","1","7","9"],"Odd places (from right) 1 + 3 + d, even places 4 + 5 + 6: (4 + d) − 15 = 0 or ±11 → d = 0.",r[0])
r = [d for d in range(10) if int(f"34{d}56")%9==0]
Q("L5","The smallest digit that can replace * in 34*56 so that it is divisible by 9 is:",["@","1","4","8"],"3 + 4 + 5 + 6 = 18 → * = 0 (or 9); smallest 0.",min(r))
r = [d for d in range(10) if int(f"76{d}58")%11==0]
Q("L5","Which digit should replace * so that 76*58 is divisible by 11?",["@","3","5","8"],"Odd places (from the right) 8 + * + 7, even places 5 + 6: (15 + *) − 11 = 4 + * must be 11 → * = 7.",r[0])
Q("L5","Which of the following numbers is divisible by 24?",["35640","35718","63810","537804"],"35640: last three 640 ÷ 8 ✓, digit sum 18 ✓ (3 × 8).")
assert 35640%24==0 and all(x%24 for x in (35718,63810,537804))
Q("L5","Which of the following numbers is divisible by 13?",["1027","1037","1047","1057"],"1027: 102 + 4 × 7 = 130 = 13 × 10 ✓.")
assert 1027%13==0 and all(x%13 for x in (1037,1047,1057))
Q("L5","Which of the following numbers is divisible by 17?",["391","381","401","371"],"391: 39 − 5 × 1 = 34 = 17 × 2 ✓.")
assert 391%17==0 and all(x%17 for x in (381,401,371))
Q("L5","Every number of the form abcabc is divisible by:",["1001","1111","1010","101"],"abcabc = abc × 1001 = abc × 7 × 11 × 13.")
Q("L5","Every number of the form ababab is divisible by:",["10101","1001","111","1111"],"ababab = ab × 10101 = ab × 3 × 7 × 13 × 37.")
r = [d for d in range(10) if int(f"4{d}6")%8==0]
Q("L5","How many digits can replace * so that 52134*6 is divisible by 8? (Hint: check 4*6)",["@","2","4","5"],"4*6 divisible by 8: 416, 456, 496 → 3 digits.",len(r))
r = [x for x in range(10) if int(f"9{x}35{x}")%3==0]
Q("L5","For how many digits x is the number 9x35x divisible by 3?",["@","4","2","5"],"17 + 2x divisible by 3 → x = 2, 5, 8 → 3 values.",len(r))
r = [x for x in range(10) if int(f"8{x}5")%45==0]
Q("L5","If 8x5 is divisible by 45, the value of x is:",["@","2","4","0"],"Ends in 5 ✓; 13 + x divisible by 9 → x = 5.",r[0])

# ---------- L6 counting multiples ----------
def cnt(a,b,f): return sum(1 for n in range(a,b+1) if f(n))
Q("L6","2^25 + 2^26 + 2^27 is divisible by:",["7","9","5","11"],"2²⁵(1 + 2 + 4) = 2²⁵ × 7.")
assert (2**25+2**26+2**27)%7==0 and all((2**25+2**26+2**27)%k for k in (9,5,11))
Q("L6","How many numbers between 300 and 700 are divisible by 5, 6 and 8?",["@","4","2","5"],"LCM 120: 360, 480, 600.",cnt(301,699,lambda n:n%120==0))
Q("L6","How many numbers from 1 to 100 are divisible by neither 3 nor 5?",["@","47","54","60"],"100 − (33 + 20 − 6) = 53.",cnt(1,100,lambda n:n%3 and n%5))
Q("L6","How many numbers from 700 to 950 (both included) are divisible by neither 3 nor 7?",["@","107","150","140"],"251 − (83 + 36 − 12) = 144.",cnt(700,950,lambda n:n%3 and n%7))
Q("L6","How many numbers from 1 to 200 are divisible by 4 but not by 6?",["@","50","16","33"],"50 − 16 = 34.",cnt(1,200,lambda n:n%4==0 and n%6))
Q("L6","How many numbers from 1 to 500 are divisible by 3 or 7?",["@","237","190","166"],"166 + 71 − 23 = 214.",cnt(1,500,lambda n:n%3==0 or n%7==0))
Q("L6","How many three-digit numbers are divisible by 7?",["@","129","130","127"],"⌊999/7⌋ − ⌊99/7⌋ = 142 − 14 = 128.",cnt(100,999,lambda n:n%7==0))
Q("L6","How many numbers between 100 and 400 are divisible by 2, 3 and 5?",["@","9","11","12"],"LCM 30: 120, 150, …, 390 → 10.",cnt(101,399,lambda n:n%30==0))
Q("L6","3^n + 3^(n+1) + 3^(n+2) is always divisible by:",["13","11","7","9"],"3ⁿ(1 + 3 + 9) = 3ⁿ × 13.")
Q("L6","The product of any three consecutive natural numbers is always divisible by:",["6","9","4","5"],"Among three consecutive numbers one is a multiple of 3 and at least one is even → 3! = 6.")
Q("L6","How many numbers from 1 to 1000 are divisible by 2, 3 or 5?",["@","700","766","733"],"500 + 333 + 200 − 166 − 100 − 66 + 33 = 734.",cnt(1,1000,lambda n:n%2==0 or n%3==0 or n%5==0))
Q("L6","How many numbers from 1 to 300 are divisible by 5 but not by 25?",["@","60","12","50"],"60 − 12 = 48.",cnt(1,300,lambda n:n%5==0 and n%25))
Q("L6","How many numbers from 1 to 120 are co-prime to 30 (divisible by none of 2, 3, 5)?",["@","40","24","30"],"120 × ½ × ⅔ × ⅘ = 32.",cnt(1,120,lambda n:math.gcd(n,30)==1))

# ---------- L7 remainders I ----------
Q("L7","On dividing a number by 38, the quotient is 24 and the remainder is 13. The number is:",["@","912","950","938"],"38 × 24 + 13 = 925.",38*24+13)
Q("L7","What is the remainder when (335 + 608 + 853) is divided by 13?",["@","5","8","10"],"10 + 10 + 8 = 28 → 2.",(335+608+853)%13)
Q("L7","What is the remainder when the sum of 47, 69 and 85 is divided by 9?",["@","1","5","0"],"2 + 6 + 4 = 12 → 3.",(47+69+85)%9)
Q("L7","Positive numbers x, y and z leave remainders 17, 24 and 27 on division by 31. The remainder when (4x − 2y + 3z) is divided by 31 is:",["@","6","13","25"],"68 − 48 + 81 = 101 → 8.",(4*17-2*24+3*27)%31)
Q("L7","Find the remainder when 179 × 172 × 173 is divided by 17.",["@","5","1","12"],"9 × 2 × 3 = 54 → 3.",(179*172*173)%17)
Q("L7","Find the remainder of 89 ÷ 9 using negative remainders.",["@","1","9","0"],"89 = 90 − 1 → −1 + 9 = 8.",89%9)
Q("L7","What is the remainder when 116 is divided by 8?",["@","2","6","0"],"116 = 120 − 4 → −4 + 8 = 4.",116%8)
Q("L7","What is the least number that must be added to 42072 to make it divisible by 93?",["@","36","45","93"],"Remainder 36 → 93 − 36 = 57.",(-42072)%93)
Q("L7","What is the least number that must be subtracted from 25809 to make it divisible by 139?",["@","45","139","85"],"25809 = 139 × 185 + 94 → subtract 94.",25809%139)
Q("L7","A number is divided successively by 3, 4 and 7, leaving remainders 2, 1 and 4. Find the least such number.",["@","71","17","74"],"7 × 0 + 4 = 4 → 4 × 4 + 1 = 17 → 17 × 3 + 2 = 53.",53)
assert 53%3==2 and (53//3)%4==1 and (53//3//4)%7==4
Q("L7","A number is divided successively by 3, 4 and 7, leaving remainders 2, 3 and 5. Find the least such number.",["@","53","59","23"],"5 → 4 × 5 + 3 = 23 → 3 × 23 + 2 = 71.",71)
assert 71%3==2 and (71//3)%4==3 and (71//3//4)%7==5
Q("L7","A number divided successively by 2, 3 and 5 leaves remainders 1, 2 and 3, the last quotient being 1. What is the remainder when it is divided by 13?",["@","3","0","2"],"5 × 1 + 3 = 8 → 26 → 53; 53 ÷ 13 leaves 1.",53%13)
Q("L7","Find the largest 4-digit number exactly divisible by 88.",["@","9988","9900","9856"],"9999 ÷ 88 leaves 55 → 9999 − 55 = 9944.",9999-9999%88)
Q("L7","Find the smallest 4-digit number exactly divisible by 88.",["@","1000","1064","1144"],"1000 ÷ 88 leaves 32 → 1000 + 56 = 1056.",1000+(-1000)%88)
Q("L7","What is the least number which leaves remainder 3 when divided by 4, 6 and 9?",["@","36","33","75"],"LCM 36 + 3 = 39.",min(n for n in range(4,500) if n%4==3 and n%6==3 and n%9==3))
Q("L7","What is the least number which, divided by 3, 5 and 8, leaves remainders 2, 4 and 7 respectively?",["@","120","121","239"],"Each remainder is 1 less than its divisor → LCM 120 − 1 = 119.",min(n for n in range(1,500) if n%3==2 and n%5==4 and n%8==7))
Q("L7","A number when divided by 5 leaves remainder 3. What is the remainder when the square of the number is divided by 5?",["@","3","9","1"],"3² = 9 → 4.",(3*3)%5)
Q("L7","A number divided by 296 leaves remainder 75. What is the remainder when the same number is divided by 37?",["@","2","8","38"],"296 = 37 × 8, so the remainder is 75 ÷ 37 → 1.",75%37)

# ---------- L8 remainders II ----------
Q("L8","Find the remainder when (8^371 + 5^371) is divided by 13.",["@","1","3","12"],"8 + 5 = 13 and the power is odd → 0.",(pow(8,371,13)+pow(5,371,13))%13)
Q("L8","Find the remainder when (3^61 + 2^61 + 4^61) is divided by 9.",["@","0","3","1"],"Not 0! 3⁶¹ → 0; 2⁶ → 1 so 2⁶¹ → 2; 4³ → 1 so 4⁶¹ → 4; 0 + 2 + 4 = 6. (The pair 2⁶¹ + 4⁶¹ is only divisible by 6.)",(pow(3,61,9)+pow(2,61,9)+pow(4,61,9))%9)
Q("L8","Find the remainder when (16^73 + 17^73 + 18^73 + 19^73) is divided by 70.",["@","1","10","35"],"16, 17, 18, 19 in AP, sum 70, odd power → 0.",sum(pow(k,73,70) for k in (16,17,18,19))%70)
Q("L8","Find the remainder when (8^36 − 2^36) is divided by 6.",["@","2","4","1"],"aⁿ − bⁿ is always divisible by a − b = 6.",(pow(8,36)-pow(2,36))%6)
Q("L8","Find the remainder when (7^24 − 4^24) is divided by 11.",["@","3","7","1"],"Even power → divisible by a + b = 11.",(pow(7,24)-pow(4,24))%11)
Q("L8","Find the remainder when 16^13 is divided by 15.",["@","0","14","13"],"(15 + 1)¹³ → 1.",pow(16,13,15))
Q("L8","Find the remainder when 72^282 is divided by 73.",["@","72","0","2"],"(73 − 1)²⁸² with even power → 1.",pow(72,282,73))
Q("L8","Find the remainder when 72^281 is divided by 73.",["@","1","0","71"],"(73 − 1)²⁸¹ with odd power → −1 → 72.",pow(72,281,73))
Q("L8","Find the remainder when 82^54 is divided by 19.",["@","18","0","5"],"Fermat: 82¹⁸ → 1, so (82¹⁸)³ → 1.",pow(82,54,19))
Q("L8","Find the remainder when 93^51 is divided by 11.",["@","1","4","6"],"93 → 5; Fermat 5¹⁰ → 1; 5⁵¹ = (5¹⁰)⁵ × 5 → 5.",pow(93,51,11))
Q("L8","Find the remainder when 9^111 is divided by 13.",["@","9","3","12"],"9³ = 729 leaves 1 → (9³)³⁷ → 1.",pow(9,111,13))
Q("L8","Find the remainder when 96^132 is divided by 97.",["@","96","0","2"],"(97 − 1)¹³² with even power → 1 (also Fermat).",pow(96,132,97))
Q("L8","Find the totient of 100.",["@","50","60","20"],"100 × ½ × ⅘ = 40.",phi(100))
Q("L8","Find the value of φ(72).",["@","36","18","12"],"72 × ½ × ⅔ = 24.",phi(72))
Q("L8","Find the remainder when 40! is divided by 41.",["@","1","0","39"],"Wilson: (p − 1)! → p − 1 = 40.",math.factorial(40)%41)
Q("L8","Find the remainder when 2^100 is divided by 7.",["@","1","4","6"],"2³ → 1; 2¹⁰⁰ = (2³)³³ × 2 → 2.",pow(2,100,7))
Q("L8","Find the remainder when 2^31 is divided by 5.",["@","2","1","4"],"Cycle 2, 4, 3, 1; 31 ÷ 4 leaves 3 → 3.",pow(2,31,5))
Q("L8","Find the remainder when 17^200 is divided by 18.",["@","17","0","2"],"(18 − 1)²⁰⁰ → (−1)²⁰⁰ = 1.",pow(17,200,18))
Q("L8","Find the remainder when 3^21 is divided by 5.",["@","1","2","4"],"3 → cycle 3, 4, 2, 1; 21 ÷ 4 leaves 1 → 3.",pow(3,21,5))

# ---------- L9 zeros ----------
def z(n): return min(vp(n,2), vp(n,5))
Q("L9","How many zeros are there at the end of 24 × 13 × 52 × 27?",["0","1","2","3"],"No factor 5 at all.")
assert (24*13*52*27)%10
Q("L9","How many zeros are there at the end of 8 × 15 × 24 × 13?",["1","2","0","3"],"Only one 5 → one zero.")
assert str(8*15*24*13).endswith("0") and not str(8*15*24*13).endswith("00")
Q("L9","Find the number of zeros at the end of 47!.",["@","9","11","12"],"9 + 1 = 10.",zeros_fact(47))
Q("L9","Find the number of zeros at the end of 300!.",["@","60","72","75"],"60 + 12 + 2 = 74.",zeros_fact(300))
Q("L9","Find the number of zeros at the end of 100!.",["@","20","25","22"],"20 + 4 = 24.",zeros_fact(100))
Q("L9","Find the number of zeros at the end of 1000!.",["@","200","248","250"],"200 + 40 + 8 + 1 = 249.",zeros_fact(1000))
Q("L9","Find the number of zeros at the end of 125!.",["@","25","30","28"],"25 + 5 + 1 = 31.",zeros_fact(125))
Q("L9","Find the highest power of 3 in 50!.",["@","16","24","17"],"16 + 5 + 1 = 22.",vp(50,3))
Q("L9","Find the highest power of 2 in 50!.",["@","25","48","43"],"25 + 12 + 6 + 3 + 1 = 47.",vp(50,2))
Q("L9","Find the highest power of 12 in 50!.",["@","23","47","24"],"2s: 47 → 23 pairs (2²); 3s: 22 → limit 22.",min(vp(50,2)//2, vp(50,3)))
Q("L9","Find the highest power of 5 in 351 × 352 × … × 600.",["@","86","148","50"],"148 − 86 = 62.",vp(600,5)-vp(350,5))
Q("L9","How many zeros are there at the end of 5 × 10 × 15 × 20 × … × 100?",["@","20","24","19"],"= 5²⁰ × 20!: 5s = 20 + 4 = 24, 2s = 18 → 18 zeros.",len(str(math.prod(range(5,101,5))))-len(str(math.prod(range(5,101,5))).rstrip('0')))
Q("L9","How many zeros are there at the end of 25 × 125 × 4?",["@","5","3","4"],"5⁵ × 2² → only two 2s → 2 zeros.",len(str(25*125*4))-len(str(25*125*4).rstrip('0')))
Q("L9","Find the highest power of 7 in 1000!.",["@","142","143","166"],"142 + 20 + 2 = 164.",vp(1000,7))

# ---------- L10 digits ----------
Q("L10","How many digits are needed to number a book of 428 pages?",["@","1284","1185","1167"],"9 + 180 + 987 = 1176.",digits_used(428))
Q("L10","A printer used 3189 digits to number the pages of a book. How many pages does the book have?",["@","1075","1063","1097"],"2889 digits up to 999; 300 more digits = 75 pages → 1074.",next(N for N in range(1,5000) if digits_used(N)==3189))
Q("L10","How many digits are used to write all numbers from 1 to 999?",["@","2700","2999","2898"],"9 + 180 + 2700 = 2889.",digits_used(999))
Q("L10","How many numbers from 400 to 700 contain the digit 6 exactly twice?",["@","18","19","21"],"466, 566, nine in 660–669, nine in 606–696 → 20.",cnt(400,700,lambda n:str(n).count('6')==2))
Q("L10","Find the sum of all digits of the numbers from 1 to 100.",["@","5050","900","946"],"45 + 450 + 405 + 1 = 901.",sum(sum(map(int,str(n))) for n in range(1,101)))
Q("L10","How many times does the digit 7 appear when writing the numbers from 1 to 100?",["@","19","21","11"],"10 in units, 10 in tens → 20.",sum(str(n).count('7') for n in range(1,101)))
Q("L10","How many numbers from 1 to 100 contain the digit 7 at least once?",["@","20","18","10"],"20 sevens, but 77 has two → 19 numbers.",cnt(1,100,lambda n:'7' in str(n)))
Q("L10","How many times does the digit 0 appear when writing the numbers from 1 to 100?",["@","10","9","20"],"10, 20, … 90 (9 zeros) + 100 (2 zeros) = 11.",sum(str(n).count('0') for n in range(1,101)))
Q("L10","How many 3-digit numbers are there in all?",["900","999","899","1000"],"100 to 999 → 999 − 100 + 1 = 900.")
Q("L10","How many 3-digit numbers have all digits different?",["@","720","729","900"],"9 × 9 × 8 = 648.",cnt(100,999,lambda n:len(set(str(n)))==3))
Q("L10","How many digits are used to write the numbers from 1 to 1000?",["@","2889","3000","2890"],"2889 + 4 = 2893.",digits_used(1000))
Q("L10","How many key strokes are needed to type the numbers from 1 to 150?",["@","450","351","339"],"1–9: 9, 10–99: 180, 100–150: 51 × 3 = 153 → 342.",digits_used(150))

# ---------- L11 difference of squares, reversal ----------
def pairs_sq(N): return [(x,y) for x in range(1,N+1) for y in range(1,x) if x*x-y*y==N]
Q("L11","How many pairs of natural numbers are there such that the difference of their squares is 35?",["@","1","3","4"],"35 × 1 → (18, 17); 7 × 5 → (6, 1).",len(pairs_sq(35)))
Q("L11","How many pairs of natural numbers have the difference of their squares equal to 36?",["@","2","3","0"],"18 × 2 → (10, 8). 6 × 6 gives y = 0, which is not natural.",len(pairs_sq(36)))
Q("L11","How many pairs of natural numbers have the difference of their squares equal to 45?",["@","2","4","1"],"45 × 1, 15 × 3, 9 × 5 → (23, 22), (9, 6), (7, 2).",len(pairs_sq(45)))
Q("L11","Which of the following can NOT be written as the difference of two perfect squares?",["30","32","35","45"],"30 = 4 × 7 + 2 is of the form 4k + 2.")
assert not pairs_sq(30) and all(pairs_sq(n) for n in (32,35,45))
Q("L11","The sum of a two-digit number and the number obtained by interchanging its digits is 77. If the digits differ by 1, the number (tens digit larger) is:",["@","34","52","61"],"x + y = 7, x − y = 1 → 43.",next(n for n in range(10,100) if n+int(str(n)[::-1])==77 and int(str(n)[0])-int(str(n)[1])==1))
Q("L11","The sum of the digits of a two-digit number is 9. The number obtained by interchanging its digits exceeds the original by 45. The number is:",["@","72","36","18"],"y − x = 5, x + y = 9 → 27.",next(n for n in range(10,100) if sum(map(int,str(n)))==9 and int(str(n)[::-1])-n==45))
Q("L11","If the hundreds and units digits of a three-digit number are interchanged, the number decreases by 198. The difference between the hundreds and units digits is:",["2","3","1","4"],"99(x − z) = 198 → 2.")
Q("L11","If the hundreds and tens digits of a three-digit number are interchanged, the number decreases by 360. The difference between the hundreds and tens digits is:",["4","3","6","2"],"90(x − y) = 360 → 4.")
Q("L11","The difference between a two-digit number and the number formed by reversing its digits is 36. What is the difference between its digits?",["4","3","6","9"],"9(x − y) = 36 → 4.")
Q("L11","The sum of a two-digit number and its reverse is always divisible by:",["11","9","10","2"],"11(x + y).")
Q("L11","A two-digit number is 4 times the sum of its digits and the number formed by reversing it is 27 more. The number is:",["@","63","24","48"],"10x + y = 4(x + y) → y = 2x; 9(y − x) = 27 → x = 3 → 36.",next(n for n in range(10,100) if n==4*sum(map(int,str(n))) and int(str(n)[::-1])-n==27))
Q("L11","Express 15 as a difference of two squares of consecutive numbers.",["8² − 7²","4² − 1²","9² − 6²","7² − 6²"],"Odd N = ((N + 1)/2)² − ((N − 1)/2)² = 8² − 7². (4² − 1² also equals 15 but is not consecutive.)")
assert 8*8-7*7==15
Q("L11","If x² − y² = 101 for natural numbers x and y, then x + y is:",["101","100","51","1"],"101 is prime → x + y = 101, x − y = 1.")

# ---------- L12 bases ----------
Q("L12","Convert (101010)₂ to octal.",["@","42","25","62"],"101 | 010 → 5, 2.",base(0b101010,8))
Q("L12","Convert (1010101)₂ to decimal.",["@","75","95","170"],"64 + 16 + 4 + 1 = 85.",0b1010101)
Q("L12","Convert (1010101)₂ to hexadecimal.",["@","45","125","A5"],"101 | 0101 → 5, 5.",base(0b1010101,16))
Q("L12","Convert (675)₈ to binary.",["@","110111110","111011101","110110101"],"6 = 110, 7 = 111, 5 = 101.",base(0o675,2))
Q("L12","Convert (175)₈ to decimal.",["@","175","135","117"],"64 + 56 + 5 = 125.",0o175)
Q("L12","Convert (675)₈ to hexadecimal.",["@","2BD","1DB","1AD"],"110111101 → 1 | 1011 | 1101 → 1BD.",base(0o675,16))
Q("L12","Convert (63)₁₀ to binary.",["@","111110","101111","1111111"],"63 = 64 − 1 → six 1s.",base(63,2))
Q("L12","Convert (67)₁₀ to octal.",["@","130","83","107"],"67 = 8 × 8 + 3 → 1, 0, 3.",base(67,8))
Q("L12","Convert (425)₁₀ to hexadecimal.",["@","1A5","19A","2A9"],"425 = 1 × 256 + 10 × 16 + 9.",base(425,16))
Q("L12","Convert (D9)₁₆ to binary.",["@","11011101","10011101","11101001"],"D = 1101, 9 = 1001.",base(0xD9,2))
Q("L12","Convert (6FD)₁₆ to octal.",["@","3357","3575","6375"],"0110 1111 1101 → 011 011 111 101.",base(0x6FD,8))
Q("L12","Convert (1AD)₁₆ to decimal.",["@","413","301","4013"],"256 + 160 + 13 = 429.",0x1AD)
Q("L12","Convert (4AE)₁₆ to octal.",["@","2265","4256","2556"],"0100 1010 1110 → 010 010 101 110 → 2256.",base(0x4AE,8))
Q("L12","Convert (10101)₂ to hexadecimal.",["@","21","25","51"],"1 | 0101 → 1, 5.",base(0b10101,16))
Q("L12","(17.125)₁₀ in binary is:",["10001.001","10001.01","10010.001","10001.101"],"17 → 10001; 0.125 → .001.")
assert 0b10001 + 0.125 == 17.125

# ---------- L13 series ----------
Q("L13","Find the sum 11² + 12² + … + 20².",["@","2870","2385","2465"],"2870 − 385 = 2485.",sum(k*k for k in range(11,21)))
Q("L13","Find the sum of all multiples of 7 between 100 and 300.",["@","5590","5537","5880"],"28 terms × (105 + 294)/2 = 5586.",sum(k for k in range(101,300) if k%7==0))
Q("L13","Find 1³ + 2³ + … + 15³.",["@","1240","3600","14000"],"(15 × 16/2)² = 120² = 14400.",sum(k**3 for k in range(1,16)))
Q("L13","Find the sum of all odd numbers from 1 to 99.",["@","2550","5000","2450"],"50 odd numbers → 50² = 2500.",sum(range(1,100,2)))
Q("L13","Find the sum of all even numbers from 2 to 100.",["@","2500","5050","2450"],"50 × 51 = 2550.",sum(range(2,101,2)))
Q("L13","Find 1 + 2 + 3 + … + 100.",["@","5000","5100","4950"],"100 × 101/2 = 5050.",sum(range(1,101)))
Q("L13","Find 1² + 2² + … + 10².",["@","355","505","3025"],"10 × 11 × 21/6 = 385.",sum(k*k for k in range(1,11)))
Q("L13","How many perfect squares are there from 1 to 500?",["@","21","23","25"],"22² = 484 ≤ 500 < 23² = 529 → 22.",cnt(1,500,lambda n:int(n**.5)**2==n))
Q("L13","How many terms are there in 7, 14, 21, …, 294?",["@","41","43","40"],"(294 − 7)/7 + 1 = 42.",len(range(7,295,7)))
Q("L13","Find 1 + 2 + 4 + 8 + … + 512.",["@","1024","511","1022"],"2¹⁰ − 1 = 1023.",sum(2**k for k in range(10)))
Q("L13","Find 2² + 4² + 6² + … + 20².",["@","770","1450","3080"],"4 × 385 = 1540.",sum(k*k for k in range(2,21,2)))
Q("L13","Find 1² + 3² + 5² + … + 19².",["@","1540","1310","1300"],"n = 10: 10 × 19 × 21/3 = 1330.",sum(k*k for k in range(1,20,2)))
Q("L13","How many numbers between 1 and 1000 are perfect cubes?",["@","9","31","100"],"1³ to 10³ → 10 (1 and 1000 included).",cnt(1,1000,lambda n:round(n**(1/3))**3==n))
Q("L13","The sum of three consecutive odd numbers is 147. The largest of them is:",["@","49","47","53"],"Middle = 147/3 = 49 → largest 51.",51)
